// Package ui holds the browser UI ccluster server serves: the build of the React app in
// the repository's ui/ directory, embedded into the binary.
//
// dist/ is generated by make ui-build and committed, so go install and the release
// builds embed the UI without Node. Do not edit it by hand.
package ui

import (
	"embed"
	"io/fs"
)

//go:embed all:dist
var dist embed.FS

// FS returns the UI's files, rooted at the directory holding index.html.
func FS() fs.FS {
	sub, err := fs.Sub(dist, "dist")
	if err != nil {
		// Only a bad literal path above makes fs.Sub fail.
		panic(err)
	}
	return sub
}
